layers.vertex:
attribute vec3 aO; attribute float aT, aK; attribute vec4 aD; uniform float uTime; varying vec2 vP, vD; varying float vU, vK, vR;
    void main(){ float u = uTime - aT; if (u < 0. || u > 7.50){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vR = aD.x; vD = aD.yz;
      if (aK < 1.5 || aK > 6.5){ float S = aD.x + .3; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., .95, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.1; float S = 1.1; mv.xy += position.xy*vec2(S*.85, S*1.05); vP = position.xy; gl_Position = projectionMatrix*mv; }
    }

layers.fragment:
uniform float uTime; uniform vec3 uGold, uOrange, uIceC, uIceP; varying vec2 vP, vD; varying float vU, vK, vR; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p - a, ba = b - a; float h = clamp(dot(pa, ba)/dot(ba, ba), 0., 1.); return length(pa - ba*h); }
    void main(){
      float lum = 0., hot = 0.;
      if (vK > 7.5){
        float r = length(vP), a = atan(-vP.y, vP.x); vec3 o;
        if (vK < 8.5){                                 // storm circle: outer + inner ring + 6 divisions, half ice / half gold, slow turn, low steady light
          float R = vR*(.3 + .7*(1. - pow(1. - clamp(vU/.5, 0., 1.), 3.)));
          float f = smoothstep(0., .15, vU)*(1. - smoothstep(6.1, 6.6, vU))*(vU < .5 ? 1. + (1. - vU/.5) : 1.);
          float side = smoothstep(-.2, .2, cos(a - vD.x)), ar = a - uTime*.12;
          float outer = exp(-pow((r - R)/.03, 2.)) + exp(-pow((r - R)/.2, 2.))*.12;
          float inner = exp(-pow((r - R*.55)/.02, 2.))*.55;
          float sp = abs(sin(ar*3.)), spoke = exp(-pow(sp*r/.025, 2.))*smoothstep(R*.55, R*.6, r)*smoothstep(R, R*.94, r)*.5;
          float wash = smoothstep(R, R*.1, r)*.025;
          vec3 c = mix(uIceC, uOrange, side), ch = mix(uIceP, uGold, side);
          o = (c*(outer*.7 + inner + spoke + wash) + ch*exp(-pow((r - R)/.01, 2.))*.3)*f;
          o *= smoothstep(vR + .3, vR + .15, r);
        } else if (vK < 9.5){                          // telegraph: ring + fill growing to the centre over the lead time, then gone at impact
          float lead = vD.y, k = clamp(vU/lead, 0., 1.), f = step(vU, lead + .03);
          vec3 c = vD.x < .5 ? uIceC : uOrange;
          float ring = exp(-pow((r - vR)/.025, 2.)), fill = smoothstep(vR*(1. - k) + .03, vR*(1. - k), vR - r)*.0 + smoothstep(vR*k + .04, vR*k - .04, r)*.075;
          o = c*(ring*.7 + fill)*f*(.6 + .4*k);
          o *= smoothstep(vR + .3, vR + .15, r);
        } else {                                       // frost ring on an ice impact
          float R = vR*(.3 + .7*(1. - pow(1. - clamp(vU/.25, 0., 1.), 3.))), f = (1. - smoothstep(.3, .6, vU));
          o = (uIceC*(exp(-pow((r - R)/.03, 2.)) + exp(-pow((r - R)/.15, 2.))*.15) + uIceP*exp(-pow((r - R)/.01, 2.))*.3)*f;
          o *= smoothstep(vR + .3, vR + .15, r);
        }
        if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); return;
      }
      if (vK > 6.5){
        // Root (only if the target was already Sapped): a ring closes onto the feet and 4 short light staples pin it, 0.45 s
        float r = length(vP), k = 1. - pow(1. - clamp(vU/.18, 0., 1.), 3.), R = mix(vR, vR*.45, k);
        float f = (vU < .033 ? 1.6 : 1.)*(1. - smoothstep(.3, .45, vU));
        lum += exp(-pow((r - R)/.02, 2.))*f; hot += lcore(r - R, .007)*f*.6;
        for (int i=0;i<4;i++){ float a = float(i)*1.5708 + .785; vec2 d = vec2(cos(a), sin(a));
          float dd = seg(vP, d*R*1.35, d*R*.8); lum += exp(-pow(dd/.02, 2.))*f*1.1; hot += lcore(dd, .006)*f*.5; }
        lum *= smoothstep(vR + .3, vR + .15, r);
      } else if (vK < .5){
        // AoE: one ring opens fast to the limit, holds a moment, fades; the limit is the brightest line
        float r = length(vP), R = vR*(.15 + .85*(1. - pow(1. - clamp(vU/.22, 0., 1.), 3.))), f = (vU < .033 ? 1.6 : 1.)*(1. - smoothstep(.35, .6, vU));
        lum += (exp(-pow(abs(r - R)/.025, 2.4)) + exp(-pow((r - R)/.18, 2.))*.12)*f; hot += lcore(r - R, .007)*f*.6;
        lum *= smoothstep(vR + .3, vR + .15, r); hot *= smoothstep(vR + .3, vR + .15, r);
      } else {
        // Shield application pulse: a thin golden rim around the body + the icon's shield drawn in line, brief (status cue keeps it)
        vec2 p = vP; float r = length(p);
        float f = smoothstep(0., .08, vU)*(vU < .1 ? 1.5 : 1.)*mix(1., .45, smoothstep(.25, .7, vU))*(1. - smoothstep(2.6, 3., vU));   // shell stays ~3 s, dimmer after the peak
        float rim = exp(-pow((r - .88)/.025, 2.)) + exp(-pow((r - .88)/.12, 2.))*.15 + smoothstep(.88, .3, r)*.05;
        vec2 e = p*vec2(1., 1.) - vec2(0., .02); float top = .3, tip = -.36, hw = .24;
        float wy = e.y > 0. ? hw : hw*clamp((e.y - tip)/(0. - tip), 0., 1.);
        float sd = max(abs(e.x) - wy, max(e.y - top, tip - e.y));
        float shield = exp(-pow(sd/.018, 2.))*.9 + step(sd, 0.)*.06;
        lum += (rim + shield)*f; hot += (lcore(r - .88, .008) + lcore(sd, .006))*f*.5;
        lum *= smoothstep(1., .96, r); hot *= smoothstep(1., .96, r);
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
